DELETE FROM products WHERE id IN ('p1','p2','p3','p4','p5','p6','p7','p8','p9','p10','p11','p12','p13','p14','p15','p16','p17','p18','p19','p20');

ON DUPLICATE KEY UPDATE
  name = VALUES(name),
  category = VALUES(category),
  price = VALUES(price),
  compare_at = VALUES(compare_at),
  badge = VALUES(badge),
  color_1 = VALUES(color_1),
  color_2 = VALUES(color_2),
  image = VALUES(image),
  sizes = VALUES(sizes),
  description = VALUES(description),
  highlights = VALUES(highlights);

DELETE FROM categories WHERE name IN ('Kaos Oversize', 'Kaos Regular', 'Cincin', 'Kalung', 'Vest Top', 'Heyfreak Kids', 'L-shirt', 'Sweater And Jacket', 'Bag', 'Footwear', 'Accessories');

ON DUPLICATE KEY UPDATE
  blurb = VALUES(blurb),
  image = VALUES(image),
  sort_order = VALUES(sort_order);

ON DUPLICATE KEY UPDATE
  title = VALUES(title),
  subtitle = VALUES(subtitle),
  image = VALUES(image),
  cta_label = VALUES(cta_label),
  cta_href = VALUES(cta_href),
  sort_order = VALUES(sort_order);

ON DUPLICATE KEY UPDATE
  image = VALUES(image),
  alt = VALUES(alt);
